import subprocess,time
P=("Create one new drawing of a single stitched-together man, in the pose and medium of <image5>. Copy from <image5> only the frontal pose with both arms raised diagonally and legs apart, the centered composition, the sepia ink line work, fine cross-hatching and the aged parchment. The figure is assembled from four different people, and each part keeps its source's look: the head and beard are exactly the face from <image1>; both arms are exactly the arms from <image2>, bare and muscular; the torso wears exactly the dark jacket, white shirt and belt from <image3>; the legs wear exactly the breeches, leg wraps and boots from <image4>. Keep clear differences between the donors in clothing, skin shading and proportions. Join the parts with thick black hand-sewn surgical stitches: a ring around the neck, a ring around each shoulder and a ring around the waist. Exactly one head, two arms and two legs, fully clothed from the waist down, no circle, no square and no handwriting, no text.")
t=time.time()
r=subprocess.run(['.mflux-venv/bin/mflux-generate-qwen-2.1-edit','--model','qwen-image-2.1-turbo','--image-paths','refs/isolated/face_lincoln.jpg','refs/isolated/arms_houdini.jpg','refs/isolated/torso_roosevelt.jpg','refs/isolated/legs_keaton.jpg','refs/isolated/pose_vitruvian.jpg','--prompt',P,'--seed','42','--quantize','8','--width','1024','--height','1024','--output-resolution','512','--output','benchmark/looks/D_parchment_with_vitruvian.png'],capture_output=True,text=True)
print('D',r.returncode,round(time.time()-t),'s'); print(r.stderr[-300:] if r.returncode else '')
